@register.simple_tag
def icon(name, size=20, css_class='', stroke_width=1.75):
    """
    Render an inline SVG icon.

    Args:
        name: icon key
        size: width/height in px
        css_class: extra CSS classes
        stroke_width: SVG stroke width
    """
    path = ICONS.get(name)
    if not path:
        return ''

    svg = (
        f'<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" '
        f'stroke-width="{stroke_width}" stroke="currentColor" '
        f'width="{size}" height="{size}" class="{css_class}" '
        f'style="display:inline-block;vertical-align:middle;" aria-hidden="true">'
        f'{path}</svg>'
    )
    return mark_safe(svg)